WITH flattened AS (SELECT src.id, src.customer_id, src.created_at, src.coupon_codes, pos + 1 AS position, elem.product_id, elem.price, elem.promo FROM carts src LATERAL VIEW POSEXPLODE(src.items) e AS pos, elem), metrics AS (SELECT *, AVG(product_id) OVER w_ordered AS running_avg_product_id, MIN(product_id) OVER w_ordered AS running_min_product_id, COUNT(product_id) OVER w_ordered AS running_count_product_id, SUM(product_id) OVER w_ordered AS running_sum_product_id, LAG(product_id, 1) OVER (PARTITION BY DATE_TRUNC('WEEK', created_at), customer_id ORDER BY position, id, position) AS prev_product_id FROM flattened WINDOW w_ordered AS (PARTITION BY customer_id, promo ORDER BY price, id, position ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT id, position, product_id, running_min_product_id, running_count_product_id, running_sum_product_id, SUM(position) OVER (PARTITION BY DATE_TRUNC('YEAR', created_at), promo ORDER BY running_sum_product_id, id, position ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_position, LAG(running_count_product_id, 1) OVER (PARTITION BY customer_id ORDER BY product_id, id, position) AS prev_running_count_product_id, AVG(price) OVER (PARTITION BY promo) AS promo_avg_price, ROW_NUMBER() OVER (PARTITION BY promo ORDER BY product_id, id, position) AS row_seq FROM metrics WHERE created_at >= '2024-03-31'), filtered AS (SELECT id, position, running_min_product_id, running_count_product_id, running_sum_product_id, cumulative_position, row_seq, CEIL(promo_avg_price) AS promo_avg_price_whole FROM enriched WHERE product_id IS NOT NULL), kept_keys AS (SELECT id FROM filtered EXCEPT DISTINCT SELECT id FROM carts WHERE created_at >= '2024-02-02'), kept_rows AS (SELECT s.* FROM filtered s JOIN kept_keys k ON s.id = k.id) SELECT CASE WHEN running_sum_product_id >= 40 THEN 'LARGE' ELSE 'SMALL' END AS running_sum_product_id_tier, running_count_product_id, MAX(running_count_product_id) AS max_running_count_product_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS row_count, COUNT(*) AS row_count_2, APPROX_PERCENTILE(running_count_product_id, 0.95) AS running_count_product_id_p95, SUM(running_sum_product_id) AS total_running_sum_product_id FROM kept_rows GROUP BY GROUPING SETS ((CASE WHEN running_sum_product_id >= 40 THEN 'LARGE' ELSE 'SMALL' END, running_count_product_id), (CASE WHEN running_sum_product_id >= 40 THEN 'LARGE' ELSE 'SMALL' END), ()) HAVING row_count_2 > 1 ORDER BY row_count_2 DESC
